"""Alternating fresh-process, real-native before/after TCSPC acceptance."""
from __future__ import annotations

import argparse
import json
import os
from pathlib import Path
import statistics
import subprocess
import sys

ROOT = Path('/Users/tpeulen/.hermes/cache/scratch/tcspc-first-fit')
REPO = Path('/Users/tpeulen/dev/chisurf')
PYTHON = '/Users/tpeulen/mambaforge/envs/arm64/bin/python'
parser = argparse.ArgumentParser()
parser.add_argument('--direct-only', action='store_true')
args = parser.parse_args()
lanes = [('direct', 'profile_tcspc.py')] if args.direct_only else [('main', 'main_tcspc.py'), ('direct', 'profile_tcspc.py')]
OUTPUT = ROOT / ('paired-direct-final' if args.direct_only else 'paired-action-guarded')
OUTPUT.mkdir(exist_ok=True)
env = dict(os.environ, QT_QPA_PLATFORM='offscreen', IMP_BFF_GPU='off',
           PYTHONPATH=str(ROOT / 'isolated-startup') +
           ':modules/chimol:modules/mmfdb/src:modules/chinet:modules/imp-tricks/src:.')
results = []
for pair in range(3):
    order = ('baseline', 'candidate') if pair % 2 == 0 else ('candidate', 'baseline')
    for variant in order:
        run_env = dict(env)
        run_env['TCSPC_BASELINE_REPOS'] = 'chisurf,emtk' if variant == 'baseline' else ''
        for lane, script in lanes:
            destination = OUTPUT / f'{pair}-{variant}-{lane}'
            command = [PYTHON, str(ROOT / script), '--output', str(destination)]
            if lane == 'main':
                command.append('--interact')
            print('RUN', pair, variant, lane, flush=True)
            with (OUTPUT / f'{pair}-{variant}-{lane}.log').open('w') as stream:
                completed = subprocess.run(command, cwd=REPO, env=run_env,
                                           stdout=stream, stderr=subprocess.STDOUT, timeout=120)
            assert completed.returncode == 0, (command, completed.returncode)
            result = json.loads((destination / 'timings.json').read_text())
            assert result['n_channels'] == 4096
            results.append(dict(pair=pair, variant=variant, lane=lane,
                                directory=str(destination), result=result))

def scientific(record):
    return [(r['model_y_sha256'], r['fit_range'],
             r.get('parameter_values', r.get('parameters')), r['plot_names'])
            for r in record['result']['runs']]

for lane, _ in lanes:
    selected = [r for r in results if r['lane'] == lane]
    reference = scientific(selected[0])
    for record in selected:
        assert scientific(record) == reference, ('Scientific parity', lane, record['directory'])
    if lane == 'direct':
        for module in ('chisurf.core.models.description', 'chisurf.core.models.model',
                       'chisurf.core.fitting.fit', 'chisurf.core.data', 'IMP.bff'):
            hashes = {r['result']['loaded_sources'][module]['sha256'] for r in selected}
            assert len(hashes) == 1, ('Concurrent native/model source changed', module, hashes)
    if lane == 'main':
        for module in ('chisurf.gui.main', 'chisurf.macros.core_fit',
                       'chisurf.history.core', 'chisurf.core.project.session',
                       'chisurf.core.project.history', 'chisurf.gui.main_helper',
                       'chisurf.core.actions._infra', 'IMP.bff'):
            hashes = {r['result']['source_hashes'][module]['sha256'] for r in selected}
            assert len(hashes) == 1, ('Concurrent source changed during measurement', module, hashes)

summary = {'acceptance_scope': 'isolated-native-fit-only' if args.direct_only else 'successful-Main-action-and-native-fit',
           'scientific_parity': True, 'pairs': 3, 'channels': 4096, 'timings': {}}
for lane, _ in lanes:
    for repetition in range(2):
        field = 'addfit_to_painted_ms' if lane == 'main' else 'total_ms'
        values = {variant: [record['result']['runs'][repetition][field] for record in results
                            if record['lane'] == lane and record['variant'] == variant]
                  for variant in ('baseline', 'candidate')}
        before = statistics.median(values['baseline'])
        after = statistics.median(values['candidate'])
        summary['timings'][f'{lane}-{"cold" if repetition == 0 else "warm"}'] = {
            'baseline_ms': before, 'candidate_ms': after, 'speedup': before / after,
            'less_time_percent': 100 * (1 - after / before), 'individual_runs_ms': values}
        if lane == 'direct':
            summary['timings'][f'{lane}-{"cold" if repetition == 0 else "warm"}']['stages'] = {
                variant: {stage: statistics.median([
                    record['result']['runs'][repetition]['stages_ms'][stage] for record in results
                    if record['lane'] == lane and record['variant'] == variant])
                    for stage in selected[0]['result']['runs'][repetition]['stages_ms']}
                for variant in ('baseline', 'candidate')}
for variant in (() if args.direct_only else ('baseline', 'candidate')):
    chosen = [record for record in results if record['lane'] == 'main' and record['variant'] == variant]
    summary.setdefault('interactions', {})[variant] = {
        'tabs': {tab['name']: statistics.median([
            record['result']['interactions']['tabs'][i]['first_visit_ms'] for record in chosen])
            for i, tab in enumerate(chosen[0]['result']['interactions']['tabs'])},
        **{name: statistics.median([record['result']['interactions'][name] for record in chosen])
           for name in ('code_first_visit_ms', 'code_reopen_ms')}}
(OUTPUT / 'raw.json').write_text(json.dumps(results, indent=2))
(OUTPUT / 'summary.json').write_text(json.dumps(summary, indent=2))
print(json.dumps(summary, indent=2), flush=True)

