"""Load the task's original clean modules without touching shared source files."""
import importlib.abc
import importlib.util
import os
from pathlib import Path
import sys

ROOT = Path(os.environ.get('TCSPC_SOURCE_ROOT', '/Users/tpeulen/.hermes/cache/scratch/tcspc-first-fit/baseline-source'))
SELECTED = set(os.environ.get('TCSPC_BASELINE_REPOS', '').split(','))
REPOS = {'chisurf': Path('/Users/tpeulen/dev/chisurf'),
         'emtk': Path('/Users/tpeulen/dev/emtk')}
MODULES = {}
for repo in SELECTED & REPOS.keys():
    for path in (ROOT / repo).rglob('*.py'):
        rel = path.relative_to(ROOT / repo)
        package = rel.name == '__init__.py'
        name = '.'.join((rel.parent if package else rel.with_suffix('')).parts)
        MODULES[name] = (path, REPOS[repo] / rel.parent if package else None)


class OriginalModules(importlib.abc.MetaPathFinder):
    def find_spec(self, fullname, path=None, target=None):
        entry = MODULES.get(fullname)
        if entry is None:
            return None
        source, package_dir = entry
        return importlib.util.spec_from_file_location(
            fullname, source,
            submodule_search_locations=[str(package_dir)] if package_dir else None)


if MODULES:
    sys.meta_path.insert(0, OriginalModules())
